// Prescribed diagnostic only: 2000 TOTAL fresh search-and-quit cycles, alternating sides.
#include "uci_process.hpp"
#include <fstream>
#include <iostream>
#include <memory>
#include <filesystem>
#include <iomanip>
using Clock=std::chrono::steady_clock;
std::string quote(const std::string& s){std::string o="\"";for(unsigned char c:s){if(c=='"'||c=='\\'){o+='\\';o+=c;}else if(c=='\n')o+="\\n";else if(c=='\r')o+="\\r";else if(c=='\t')o+="\\t";else if(c<32){static const char h[]="0123456789abcdef";o+="\\u00";o+=h[c>>4];o+=h[c&15];}else o+=c;}return o+'"';}
const char* boolean(bool b){return b?"true":"false";}
int left(Clock::time_point until){return static_cast<int>(std::max<std::int64_t>(0,std::chrono::duration_cast<std::chrono::milliseconds>(until-Clock::now()).count()));}
int main(int argc,char**argv){try{
 if(argc!=7)throw std::runtime_error("arguments: OUT FEN_FILE CANDIDATE REFERENCE SECONDS ABSOLUTE_DEADLINE_EPOCH_MS");
 const std::string dir=argv[1];std::ifstream fen_input(argv[2]);std::string fen,extra;if(!std::getline(fen_input,fen)||fen.empty()||std::getline(fen_input,extra))throw std::runtime_error("exactly one FEN line required");const int seconds=std::stoi(argv[5]);if(seconds<1||seconds>390)throw std::runtime_error("seconds outside1..390");const std::int64_t epoch_ms=std::stoll(argv[6]),now_epoch=std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count();const auto started=Clock::now(),deadline=started+std::chrono::milliseconds(std::max<std::int64_t>(0,std::min<std::int64_t>(seconds*1000,epoch_ms-now_epoch-1000)));
 std::cout<<"{\"type\":\"config\",\"target_cycles\":2000,\"cycles_per_side\":1000,\"first_side\":\"candidate\",\"fresh_process_per_cycle\":true,\"depth\":9,\"Threads\":1,\"Hash\":16,\"OwnBook\":false,\"HindsightDepth\":\"default_false\",\"MateAlphaGuard\":\"default_false\",\"shutdown_budget_ms\":250,\"seconds\":"<<seconds<<",\"absolute_deadline_epoch_ms\":"<<epoch_ms<<",\"fen\":"<<quote(fen)<<",\"candidate\":"<<quote(argv[3])<<",\"reference\":"<<quote(argv[4])<<"}"<<std::endl;
 int finalized=0,searched_count=0,quit_sent=0,observed=0,candidate_count=0,reference_count=0;bool limited=false;
 for(int cycle=1;cycle<=2000;++cycle){if(left(deadline)<=1000){limited=true;break;}const bool candidate=cycle%2==1;const std::string side=candidate?"candidate":"reference",binary=argv[candidate?3:4];std::ostringstream name;name<<dir<<"/cycle-"<<std::setw(4)<<std::setfill('0')<<cycle<<'-'<<side<<".transcript.txt";const auto file=name.str();if(std::filesystem::exists(file))throw std::runtime_error("existing transcript refused");
  std::cout<<"{\"type\":\"cycle_started\",\"cycle\":"<<cycle<<",\"side\":"<<quote(side)<<",\"transcript\":"<<quote(file)<<"}"<<std::endl;
  const auto cycle_start=Clock::now(),normal_limit=cycle_start+std::chrono::seconds(15),work_limit=deadline-std::chrono::milliseconds(500),cycle_limit=std::min(normal_limit,work_limit);const bool global_clipped=work_limit<normal_limit;std::unique_ptr<UciProcess> process;UciResult result;UciShutdownResult shutdown;std::string error;bool searched=false,shutdown_observed=false,defaults_ok=false;
  try{process=std::make_unique<UciProcess>(binary,1,std::max(1,left(cycle_limit)));const auto& startup=process->transcript();defaults_ok=startup.find("option name HindsightDepth type check default false")!=std::string::npos&&startup.find("option name MateAlphaGuard type check default false")!=std::string::npos;if(!defaults_ok)throw std::runtime_error("required default-false advertisement missing");if(left(cycle_limit)<=0)throw std::runtime_error("diagnostic response timeout before search");result=process->search(fen,9,std::max(1,left(cycle_limit)),true);searched=true;}
  catch(const std::exception& e){error=e.what();if(const auto* startup=dynamic_cast<const UciStartupError*>(&e)){shutdown=startup->shutdown;shutdown_observed=true;}}
  const bool budget_interrupted=global_clipped&&!searched&&left(cycle_limit)<=0&&error.find("timeout")!=std::string::npos;
  if(process){shutdown=process->finish(250);shutdown_observed=true;}
  std::ofstream trace(file);trace.exceptions(std::ios::badbit|std::ios::failbit);trace<<(process?process->transcript():error);trace.close();
  std::string pv="[";for(std::size_t i=0;i<result.pv.size();++i){if(i)pv+=',';pv+=quote(result.pv[i]);}pv+=']';
  std::cout<<"{\"type\":\"cycle\",\"cycle\":"<<cycle<<",\"side\":"<<quote(side)<<",\"binary\":"<<quote(binary)<<",\"fen\":"<<quote(fen)<<",\"searched\":"<<boolean(searched)<<",\"defaults_ok\":"<<boolean(defaults_ok)<<",\"budget_interrupted\":"<<boolean(budget_interrupted)<<",\"error\":"<<quote(error)<<",\"depth\":"<<result.depth<<",\"bestmove\":"<<quote(result.move)<<",\"score_kind\":"<<quote(result.score_kind)<<",\"score\":"<<result.score<<",\"bound\":"<<quote(result.score_bound)<<",\"nodes\":"<<result.nodes<<",\"pv\":"<<pv<<",\"shutdown\":{\"observed\":"<<boolean(shutdown_observed)<<",\"reaped\":"<<boolean(shutdown.reaped)<<",\"exit_code\":"<<shutdown.exit_code<<",\"signal\":"<<shutdown.signal<<",\"timed_out\":"<<boolean(shutdown.timed_out)<<",\"driver_sigterm\":"<<boolean(shutdown.driver_sigterm)<<",\"driver_sigkill\":"<<boolean(shutdown.driver_sigkill)<<",\"error\":"<<quote(shutdown.error)<<",\"timing_schema\":1,\"shutdown_budget_ms\":"<<shutdown.shutdown_budget_ms<<",\"quit_attempted\":"<<boolean(shutdown.quit_attempted)<<",\"quit_sent\":"<<boolean(shutdown.quit_sent)<<",\"quit_to_exit_ms\":"<<(shutdown.quit_to_exit_ms<0?"null":std::to_string(shutdown.quit_to_exit_ms))<<",\"shutdown_total_ms\":"<<shutdown.shutdown_total_ms<<"},\"transcript\":"<<quote(file)<<"}"<<std::endl;
  ++finalized;searched_count+=searched;quit_sent+=shutdown.quit_sent;observed+=shutdown.reaped;if(candidate)++candidate_count;else ++reference_count;
 }
 const bool complete=finalized==2000&&searched_count==2000&&quit_sent==2000&&observed==2000;
 std::cout<<"{\"type\":\"summary\",\"target_cycles\":2000,\"finalized_cycles\":"<<finalized<<",\"candidate_cycles\":"<<candidate_count<<",\"reference_cycles\":"<<reference_count<<",\"searched\":"<<searched_count<<",\"quit_sent\":"<<quit_sent<<",\"exit_observed\":"<<observed<<",\"time_limited\":"<<boolean(limited)<<",\"complete_2000_search_quit_cycles\":"<<boolean(complete)<<"}"<<std::endl;return complete?0:3;
}catch(const std::exception& e){std::cerr<<"{\"type\":\"fatal\",\"error\":"<<quote(e.what())<<"}"<<std::endl;return 3;}}
